1	import { useMemo, useState } from 'react';
2	import { useSearchParams } from 'react-router-dom';
3	import { LinhaOrcamentoItem } from '../components/LinhaOrcamentoItem';
4	import { Alerta, Botao, Cartao, CampoTexto, EstadoVazio, TituloPagina } from '../components/ui';
5	import { hojeISO, mesDe, mesValido, nomeMes, somarMeses } from '../domain/date';
6	import { formatarMoeda } from '../domain/money';
7	import { copiarMesAnterior, definirLimite, linhasOrcamento, mesTemLimites, removerLimite, totaisOrcamento } from '../domain/orcamento';
8	import { useEstado, useStore } from '../state/store';
9	
10	export function OrcamentoPage() {
11	  const store = useStore();
12	  const estado = useEstado();
13	  const [params, setParams] = useSearchParams();
14	  const [erro, setErro] = useState<string | null>(null);
15	
16	  const mesParam = params.get('mes') ?? '';
17	  const mes = mesValido(mesParam) ? mesParam : mesDe(hojeISO());
18	  const irPara = (novo: string) => setParams({ mes: novo }, { replace: true });
19	
20	  const linhas = useMemo(() => linhasOrcamento(estado, mes), [estado, mes]);
21	  const totais = useMemo(() => totaisOrcamento(linhas), [linhas]);
22	  const semLimites = !mesTemLimites(estado, mes);
23	  const podeCopiar = semLimites && mesTemLimites(estado, somarMeses(mes, -1));
24	  const estouradas = linhas.filter((l) => l.estado === 'estourado').length;
25	
26	  return (
27	    <div>
28	      <TituloPagina>Orçamento</TituloPagina>
29	      <div className="space-y-4">
30	        <Cartao>
31	          <div className="flex flex-wrap items-end gap-3">
32	            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, -1))}>
33	              Mês anterior
34	            </Botao>
35	            <div className="w-44">
36	              <CampoTexto label="Mês" type="month" value={mes} onChange={(e) => mesValido(e.target.value) && irPara(e.target.value)} />
37	            </div>
38	            <Botao variante="secundario" onClick={() => irPara(somarMeses(mes, 1))}>
39	              Próximo mês
40	            </Botao>
41	            <p className="ml-auto text-lg font-semibold capitalize text-slate-800" aria-live="polite">
42	              {nomeMes(mes)}
43	            </p>
44	          </div>
45	        </Cartao>
46	
47	        {erro ? <Alerta>{erro}</Alerta> : null}
48	
49	        {podeCopiar ? (
50	          <Alerta tipo="aviso">
51	            <span className="flex flex-wrap items-center justify-between gap-2">
52	              Este mês ainda não tem limites. Quer copiar os do mês anterior?
53	              <Botao
54	                variante="secundario"
55	                onClick={() => {
56	                  const r = store.aplicar((s) => copiarMesAnterior(s, mes));
57	                  setErro(r.ok ? null : r.erro);
58	                }}
59	              >
60	                Copiar limites do mês anterior
61	              </Botao>
62	            </span>
63	          </Alerta>
64	        ) : null}
65	
66	        {linhas.length === 0 ? (
67	          <EstadoVazio titulo="Nenhuma categoria de despesa">Crie categorias de despesa na tela Transações para definir limites.</EstadoVazio>
68	        ) : (
69	          <>
70	            <div className="grid gap-3 sm:grid-cols-3" role="group" aria-label="Totais do mês">
71	              <Cartao>
72	                <p className="text-sm text-slate-600">Soma dos limites</p>
73	                <p className="text-xl font-bold" data-testid="total-limites">{formatarMoeda(totais.limites)}</p>
74	              </Cartao>
75	              <Cartao>
76	                <p className="text-sm text-slate-600">Gasto nas categorias com limite</p>
77	                <p className="text-xl font-bold" data-testid="total-gasto-com-limite">{formatarMoeda(totais.gastoComLimite)}</p>
78	              </Cartao>
79	              <Cartao>
80	                <p className="text-sm text-slate-600">Gasto sem orçamento</p>
81	                <p className="text-xl font-bold" data-testid="total-gasto-sem-orcamento">{formatarMoeda(totais.gastoSemOrcamento)}</p>
82	              </Cartao>
83	            </div>
84	            {estouradas > 0 ? (
85	              <Alerta>
86	                {estouradas === 1 ? '1 categoria estourou' : `${estouradas} categorias estouraram`} o limite neste mês.
87	              </Alerta>
88	            ) : null}
89	            <Cartao titulo="Limites por categoria">
90	              <ul className="divide-y divide-slate-200">
91	                {linhas.map((l) => (
92	                  <LinhaOrcamentoItem
93	                    key={l.categoria.id}
94	                    linha={l}
95	                    onDefinir={(limite) => store.aplicar((s) => definirLimite(s, l.categoria.id, mes, limite))}
96	                    onRemover={() => store.aplicar((s) => removerLimite(s, l.categoria.id, mes))}
97	                  />
98	                ))}
99	              </ul>
100	            </Cartao>
101	          </>
102	        )}
103	      </div>
104	    </div>
105	  );
106	}
